def clean_text(value: object, limit: int = 80) -> str:
    text = " ".join(str(value or "").strip().split())
    return text[:limit].rstrip()


def topic_key(value: object) -> str:
    text = clean_text(value, 120)
    normalized = unicodedata.normalize("NFKD", text)
    ascii_text = normalized.encode("ascii", "ignore").decode("ascii")
    key = re.sub(r"[^a-z0-9]+", "-", ascii_text.casefold()).strip("-")
    return key or "thema"


def read_json_object(path: Path) -> dict[str, Any] | None:
    try:
        value = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return None
    return value if isinstance(value, dict) else None


def write_json_atomic(path: Path, value: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(
        json.dumps(value, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    temporary.replace(path)


def find_project_root() -> Path:
    script_dir = Path(__file__).resolve().parent
    override = os.environ.get("ZUSTAND_PROJECT_ROOT", "").strip()
    if override:
        candidate = Path(override).expanduser().resolve()
        if (candidate / "newsredaktion").exists() or (candidate / "news.json").exists():
            return candidate

    candidates = [script_dir, *script_dir.parents]

    def score(candidate: Path) -> int:
        value = 0
        if (candidate / "newsredaktion").is_dir():
            value += 100
        if (candidate / "assets" / "images").is_dir():
            value += 30
        if (candidate / "news.json").exists():
            value += 20
        if (candidate / "index.html").exists():
            value += 5
        return value

    ranked = sorted(
        ((score(candidate), index, candidate) for index, candidate in enumerate(candidates)),
        key=lambda item: (-item[0], item[1]),
    )
    return ranked[0][2] if ranked and ranked[0][0] > 0 else script_dir


def extract_runtime(runtime_dir: Path) -> None:
    for filename, encoded in EMBEDDED_SOURCES.items():
        source = zlib.decompress(base64.b85decode(encoded.encode("ascii")))
        (runtime_dir / filename).write_bytes(source)


def load_runtime_module(runtime_dir: Path):
    module_path = runtime_dir / "news_studio_5_21.py"
    spec = importlib.util.spec_from_file_location("zustand_news_studio_5_21_runtime", module_path)
    if spec is None or spec.loader is None:
        raise RuntimeError("Die eingebettete Studio-Laufzeit konnte nicht geladen werden.")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def build_topic_metadata(
    payload: dict[str, Any],
    source_records: dict[str, dict[str, Any]],
) -> int:
    raw_articles = payload.get("articles")
    if not isinstance(raw_articles, list):
        raise ValueError("news.json enthält keine Artikelliste.")

    articles = [item for item in raw_articles if isinstance(item, dict)]
    by_id = {clean_text(item.get("id"), 120): item for item in articles}
    explainer_topics: dict[str, str] = {}
    explicit_topics: set[str] = set()

    for identifier, record in source_records.items():
        if record.get("contentType") != "explainer":
            continue
        article = record.get("article") if isinstance(record.get("article"), dict) else {}
        explicit = clean_text(article.get("topic") or article.get("selectionLabel"), 60)
        fallback = clean_text(record.get("title") or identifier, 80)
        label = explicit or fallback
        if not label:
            continue
        explainer_topics[identifier] = label
        if explicit:
            explicit_topics.add(identifier)

        exported = by_id.get(identifier)
        if exported is not None:
            exported["topic"] = label
            exported["topicIsFallback"] = identifier not in explicit_topics
            exported.pop("selectionLabel", None)

    for article in articles:
        identifier = clean_text(article.get("id"), 120)
        if identifier in explainer_topics:
            continue
        linked_id = clean_text(article.get("explainerId"), 120)
        label = explainer_topics.get(linked_id, "")
        if label:
            article["topic"] = label
            article["topicSource"] = "linked-explainer"
        else:
            article.pop("topic", None)
            article.pop("topicSource", None)
            article.pop("topicIsFallback", None)
        article.pop("selectionLabel", None)

    for group in payload.get("playbackGroups", []) if isinstance(payload.get("playbackGroups"), list) else []:
        if not isinstance(group, dict):
            continue
        explainer_id = clean_text(group.get("explainerId"), 120)
        label = explainer_topics.get(explainer_id, "")
        if label:
            group["topic"] = label
            group["topicKey"] = topic_key(label)
        else:
            group.pop("topic", None)
            group.pop("topicKey", None)

    topics: OrderedDict[str, dict[str, Any]] = OrderedDict()
    for article in articles:
        label = clean_text(article.get("topic"), 80)
        if not label:
            continue
        folded = label.casefold()
        entry = topics.setdefault(
            folded,
            {
                "key": topic_key(label),
                "label": label,
                "explainerIds": [],
                "articleIds": [],
                "articleCount": 0,
            },
        )
        identifier = clean_text(article.get("id"), 120)
        if identifier and identifier not in entry["articleIds"]:
            entry["articleIds"].append(identifier)
        if article.get("contentType") == "explainer" and identifier:
            if identifier not in entry["explainerIds"]:
                entry["explainerIds"].append(identifier)

    for entry in topics.values():
        entry["articleCount"] = len(entry["articleIds"])
        entry["explainerCount"] = len(entry["explainerIds"])

    payload["topics"] = list(topics.values())
    payload["topicCount"] = len(topics)
    payload["topicPolicy"] = {
        "source": "explainer.topic",
        "fallback": "explainer.title",
        "linkedNews": "inherit-topic-from-explainerId",
        "standaloneNews": "only-in-all-topics",
    }
    try:
        schema = int(payload.get("contentSchema", 0) or 0)
    except (TypeError, ValueError):
        schema = 0
    payload["contentSchema"] = max(schema, 7)
    return len(topics)


def create_app_class(runtime):
    tk = runtime.tk
    ttk = runtime.ttk

    class NewsStudio523(runtime.NewsStudio521):
        def __init__(self):
            self._topic_editor_ready = False
            super().__init__()
            self.title("ZUSTAND News Studio 5.23.1")
            try:
                self._replace_widget_text(
                    "ZUSTAND News Studio 5.21",
                    "ZUSTAND News Studio 5.23.1",
                )
            except Exception:
                pass
            self.after_idle(self._install_topic_editor)
            self.status_var.set(
                "News Studio 5.23.1 bereit │ eigenständig │ sichtbares Themenfeld"
            )

        def _load_records(self):
            records = super()._load_records()
            for record in records.values():
                article = record.get("article") if isinstance(record.get("article"), dict) else {}
                record["topic"] = clean_text(
                    article.get("topic") or article.get("selectionLabel"),
                    60,
                )
            return records

        def _effective_topic(self, record: dict[str, Any]) -> str:
            return clean_text(record.get("topic"), 60) or clean_text(
                record.get("title") or record.get("id"), 80
            )

        def _existing_topic_values(self) -> tuple[str, ...]:
            values = {
                clean_text(record.get("topic"), 60)
                for record in self._playback_records.values()
                if record.get("contentType") == "explainer"
                and clean_text(record.get("topic"), 60)
            }
            return tuple(sorted(values, key=str.casefold))

        def _install_topic_editor(self) -> None:
            if self._topic_editor_ready:
                return
            tab = getattr(self, "playback_tab", None)
            if tab is None:
                self.after(200, self._install_topic_editor)
                return

            box = ttk.LabelFrame(tab, text="Thema der ausgewählten Grundlage", padding=8)

            # In 5.23 wurde der Themenbereich hinter dem großen, expandierenden
            # Panedwindow eingepackt und konnte bei üblichen Bildschirmhöhen
            # unterhalb des sichtbaren Fensters liegen. Deshalb wird er jetzt
            # ausdrücklich VOR der geteilten Hauptansicht angeordnet.
            playback_body = None
            try:
                for child in tab.winfo_children():
                    if child is box:
                        continue
                    if child.winfo_class() in {"TPanedwindow", "Panedwindow"}:
                        playback_body = child
                        break
            except Exception:
                playback_body = None

            if playback_body is not None:
                box.pack(fill="x", pady=(0, 10), before=playback_body)
            else:
                box.pack(fill="x", pady=(10, 0))

            row = ttk.Frame(box)
            row.pack(fill="x")
            ttk.Label(row, text="Thema:").pack(side="left")
            self.topic_var = tk.StringVar()
            self.topic_combo = ttk.Combobox(
                row,
                textvariable=self.topic_var,
                values=self._existing_topic_values(),
                state="disabled",
                width=38,
            )
            self.topic_combo.pack(side="left", fill="x", expand=True, padx=(8, 8))
            self.topic_save_button = ttk.Button(
                row,
                text="Thema speichern",
                command=self._save_topic,
                state="disabled",
            )
            self.topic_save_button.pack(side="left")

            self.topic_hint_var = tk.StringVar(
                value=(
                    "Eine Grundlage auswählen. Mehrere Grundlagen dürfen dasselbe Thema "
                    "tragen. Ohne Eintrag wird der vollständige Titel als Thema verwendet."
                )
            )
            ttk.Label(
                box,
                textvariable=self.topic_hint_var,
                wraplength=1080,
                justify="left",
            ).pack(anchor="w", pady=(6, 0))

            self.playback_tree.bind(
                "<<TreeviewSelect>>",
                self._on_topic_selection,
                add="+",
            )
            self.topic_combo.bind("<Return>", lambda _event: self._save_topic())
            self._topic_editor_ready = True
            self._annotate_topic_blocks()

        def _selected_explainer_record(self):
            try:
                _item_id, meta = self._selected_meta()
            except Exception:
                return None
            if not meta or meta.get("kind") not in {"explainer-block", "explainer-marker"}:
                return None
            record = self._playback_records.get(meta.get("id", ""))
            if not record or record.get("contentType") != "explainer":
                return None
            return record

        def _on_topic_selection(self, _event=None) -> None:
            if not self._topic_editor_ready:
                return
            record = self._selected_explainer_record()
            if record is None:
                self.topic_var.set("")
                self.topic_combo.configure(state="disabled")
                self.topic_save_button.configure(state="disabled")
                self.topic_hint_var.set("Bitte einen Grundlagenblock auswählen.")
                return

            explicit = clean_text(record.get("topic"), 60)
            preview = self._effective_topic(record)
            self.topic_var.set(explicit)
            self.topic_combo.configure(
                state="normal",
                values=self._existing_topic_values(),
            )
            self.topic_save_button.configure(state="normal")
            if explicit:
                self.topic_hint_var.set(f"Gespeichertes Thema: {explicit}")
            else:
                self.topic_hint_var.set(
                    f"Noch kein eigenes Thema. Derzeitiger Rückfallwert: {preview}"
                )

        def _save_topic(self) -> None:
            record = self._selected_explainer_record()
            if record is None:
                return
            path = Path(record["path"])
            article = read_json_object(path)
            if article is None:
                messagebox.showerror(
                    "Thema konnte nicht gespeichert werden",
                    "Die Artikeldatei konnte nicht gelesen werden.",
                    parent=self,
                )
                return

            label = clean_text(self.topic_var.get(), 60)
            if label:
                article["topic"] = label
            else:
                article.pop("topic", None)
            article.pop("selectionLabel", None)

            try:
                write_json_atomic(path, article)
            except OSError as exc:
                messagebox.showerror(
                    "Thema konnte nicht gespeichert werden",
                    str(exc),
                    parent=self,
                )
                return

            record["article"] = article
            record["topic"] = label
            selected_id = record.get("id", "")
            self._refresh_playback_view()
            for item_id, meta in self._playback_item_meta.items():
                if meta.get("kind") == "explainer-block" and meta.get("id") == selected_id:
                    self.playback_tree.selection_set(item_id)
                    self.playback_tree.see(item_id)
                    break
            self._on_topic_selection()
            self.status_var.set(
                f"Thema gespeichert │ {selected_id} │ {label or 'Titel als Rückfallwert'}"
            )

        def _annotate_topic_blocks(self) -> None:
            tree = getattr(self, "playback_tree", None)
            if tree is None:
                return
            for item_id, meta in self._playback_item_meta.items():
                if meta.get("kind") != "explainer-block":
                    continue
                record = self._playback_records.get(meta.get("id", ""), {})
                label = self._effective_topic(record)
                try:
                    current = str(tree.item(item_id, "text") or "")
                    current = re.sub(r"\s+\[Thema:.*?\]$", "", current)
                    tree.item(item_id, text=f"{current}  [Thema: {label}]")
                except Exception:
                    pass

        def _refresh_playback_view(self):
            result = super()._refresh_playback_view()
            self._annotate_topic_blocks()
            if self._topic_editor_ready:
                self.topic_combo.configure(values=self._existing_topic_values())
                self._on_topic_selection()
            return result

        def _apply_manual_order_to_news_json(self):
            stats = super()._apply_manual_order_to_news_json()
            payload = read_json_object(runtime.OUTPUT_PATH)
            if payload is None:
                raise ValueError("news.json konnte nach der Erzeugung nicht gelesen werden.")
            self._playback_records = self._load_records()
            topic_count = build_topic_metadata(payload, self._playback_records)
            write_json_atomic(runtime.OUTPUT_PATH, payload)
            stats["topics"] = topic_count
            return stats

        def run_generator(self):
            super().run_generator()
            payload = read_json_object(runtime.OUTPUT_PATH)
            if payload is None:
                return
            topic_count = int(payload.get("topicCount", 0) or 0)
            if topic_count:
                self.status_var.set(
                    f'news.json erzeugt │ {payload.get("articleCount", 0)} Beiträge │ '
                    f'{topic_count} Themen'
                )
                if hasattr(self, "generator_log"):
                    try:
                        self.generator_log.configure(state="normal")
                        self.generator_log.insert(
                            "end",
                            "\n\nTHEMENAUSWAHL 5.23.1\n"
                            f"✓ {topic_count} Themen exportiert\n"
                            "✓ News übernehmen das Thema ihrer Grundlage\n"
                            "✓ Beiträge ohne Grundlage erscheinen unter ‚Alle Themen‘\n",
                        )
                        self.generator_log.configure(state="disabled")
                        self.generator_log.see("end")
                    except Exception:
                        pass

    return NewsStudio523


def run_self_test(runtime) -> int:
    required = [
        "NewsStudio521",
        "OUTPUT_PATH",
        "tk",
        "ttk",
    ]
    missing = [name for name in required if not hasattr(runtime, name)]
    if missing:
        raise RuntimeError("Fehlende Laufzeitbestandteile: " + ", ".join(missing))
    print("ZUSTAND News Studio 5.23.1: Selbsttest erfolgreich")
    print(f"Projektordner: {os.environ.get('ZUSTAND_PROJECT_ROOT', '')}")
    print(f"Eingebettete Module: {len(EMBEDDED_SOURCES)}")
    return 0


def main() -> int:
    project_root = find_project_root()
    os.environ["ZUSTAND_PROJECT_ROOT"] = str(project_root)

    try:
        with tempfile.TemporaryDirectory(prefix="zustand_studio_523_") as temporary:
            runtime_dir = Path(temporary)
            extract_runtime(runtime_dir)
            runtime = load_runtime_module(runtime_dir)

            if "--self-test" in sys.argv:
                return run_self_test(runtime)

            app_class = create_app_class(runtime)
            app = app_class()
            app.mainloop()
            return 0
    except BaseException as exc:
        if isinstance(exc, KeyboardInterrupt):
            raise
        log_path = project_root / "news_studio_5_23_1_startfehler.txt"
        try:
            log_path.write_text(
                "ZUSTAND News Studio 5.23.1 konnte nicht gestartet werden.\n\n"
                f"Fehlertyp: {type(exc).__name__}\n"
                f"Fehler: {exc}\n\n"
                "Technische Details:\n"
                + traceback.format_exc(),
                encoding="utf-8",
            )
        except OSError:
            pass
        try:
            messagebox.showerror(
                "News Studio 5.23.1 – Startfehler",
                f"{type(exc).__name__}: {exc}\n\nFehlerbericht:\n{log_path}",
            )
        except Exception:
            pass
        print(f"News Studio 5.23.1 – Startfehler: {exc}", file=sys.stderr)
        print(f"Fehlerbericht: {log_path}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
